        assert_eq!(
            bounded_chunk_range(block_count, chunk, PLONKY3_HASH_CHUNK_ITEMS_V2)
                .unwrap()
                .len(),
            usize::from(PLONKY3_HASH_CHUNK_ITEMS_V2),
        );
        (encode_event_vector(&events), chunk_count)
