    fn uniqueness_list_air_fixture(stale: bool) -> Vec<u8> {
        let profile = RecursiveCircuitProfileV2::authority_pinned();
        let precommit = uniqueness_precommit_from_rows(&[], &[]).unwrap();
        let source_payloads = [
            (
                RecursiveTraceOpcodeV2::UniquenessPrecommit,
                encode_uniqueness_precommit_value(precommit).unwrap(),
            ),
            (
                RecursiveTraceOpcodeV2::UniquenessChallenge,
                encode_uniqueness_challenge([0x55; 32], [0x66; 32], precommit),
            ),
        ];
        let sources = source_payloads
            .into_iter()
            .enumerate()
            .map(|(ordinal, (opcode, payload))| {
                let ordinal = u64::try_from(ordinal).unwrap();
                RecursiveTraceEventV2::new(
                    ordinal,
                    opcode,
                    structural_event_id(opcode, ordinal, &payload),
                    payload,
                    &profile,
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let mut events = Vec::new();
        emit_test_uniqueness_list_hash(&sources, &profile, |event| {
            events.push(event);
            Ok(())
        })
        .unwrap();

        if stale {
            let block = events
                .iter_mut()
                .find(|event| {
                    decode_hash_control(event)
                        .map(|control| {
                            control.schema == HashControlSchemaV2::UniquenessList
                                && control.stage == HashControlStageV2::Block
                                && control
                                    .uniqueness_list
                                    .map(|binding| {
                                        binding.job == UniquenessListHashJobV2::SpentOriginal
                                    })
                                    .unwrap_or(false)
                        })
                        .unwrap_or(false)
                })
                .expect("spent-original uniqueness-list block");
            let mut payload = block.payload().to_vec();
            payload[UNIQUENESS_LIST_COMMON_BYTES_V2 + 16] ^= 1;
            *block = RecursiveTraceEventV2::new(
                block.ordinal(),
                block.opcode(),
                structural_event_id(block.opcode(), block.ordinal(), &payload),
                payload,
                &profile,
            )
            .unwrap();
        }
        encode_event_vector(&events)
    }

    fn uniqueness_transcript_air_fixture(missing_job: bool) -> (Vec<u8>, Vec<u8>) {
        let profile = RecursiveCircuitProfileV2::authority_pinned();
        let declared_work = RecursiveDeclaredWorkV2::new(
            RecursiveTraceEventCountsV2::default(),
            0,
            0,
            0,
            0,
            0,
            0,
            0,
            0,
        )
        .unwrap();
        let layout = 7;
        let policy_digest = [0x12; 32];
        let old_definition_root = [0x15; 32];
        let post_definition_root = [0x1c; 32];
        let old_settlement_root = *crate::settlement::derive_settlement_root_v2(
            crate::settlement::RootGeneration::SettlementV2,
            layout,
            policy_digest,
            old_definition_root,
        )
        .unwrap()
        .as_bytes();
        let post_settlement_root = *crate::settlement::derive_settlement_root_v2(
            crate::settlement::RootGeneration::SettlementV2,
            layout,
            policy_digest,
            post_definition_root,
        )
        .unwrap()
        .as_bytes();
        let context = RecursivePreUniquenessContextV2::from_parts(
            [0x10; 32],
            [0x11; 32],
            policy_digest,
            [0x13; 32],
            1,
            0,
            layout,
            1,
            1,
            1_000,
            old_settlement_root,
            old_definition_root,
            [0x16; 32],
            [0x17; 32],
            [0x18; 32],
            [0x19; 32],
            [0x1a; 32],
            RecursiveTraceOpcodeV2::grammar_digest(),
            [0x1b; 32],
            declared_work,
        )
        .unwrap();
        let precommit = uniqueness_precommit_from_rows(&[], &[]).unwrap();
        let challenge = encode_uniqueness_challenge(
            context.digest(),
            RecursiveTraceOpcodeV2::grammar_digest(),
            precommit,
        );
        let source_payloads = [
            (
                RecursiveTraceOpcodeV2::UniquenessPrecommit,
                encode_uniqueness_precommit_value(precommit).unwrap(),
            ),
            (
                RecursiveTraceOpcodeV2::UniquenessChallenge,
                challenge.clone(),
            ),
        ];
        let sources = source_payloads
            .into_iter()
            .enumerate()
            .map(|(ordinal, (opcode, payload))| {
                let ordinal = u64::try_from(ordinal).unwrap();
                RecursiveTraceEventV2::new(
                    ordinal,
                    opcode,
                    structural_event_id(opcode, ordinal, &payload),
                    payload,
                    &profile,
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let mut events = Vec::new();
        for source in &sources {
            events.push(source.clone());
            emit_derived_hash_controls(source, &profile, |control| {
                events.push(control);
                Ok(())
            })
            .unwrap();
        }
        emit_test_uniqueness_transcript_hash(
            context,
            precommit,
            post_definition_root,
            post_settlement_root,
            u64::try_from(sources.len()).unwrap(),
            &profile,
            |control| {
                events.push(control);
                Ok(())
            },
        )
        .unwrap();

        let mut statement = base_statement_bytes_for_test();
        let grammar_start =
            PLONKY3_STATEMENT_DIGESTS_OFFSET_V2 + STATEMENT_GRAMMAR_DIGEST_INDEX_V2 * 32;
        statement[grammar_start..grammar_start + 32]
            .copy_from_slice(&RecursiveTraceOpcodeV2::grammar_digest());
        for (index, digest) in [
            (
                STATEMENT_PRE_SETTLEMENT_INDEX_V2,
                context.old_settlement_root(),
            ),
            (STATEMENT_POST_SETTLEMENT_INDEX_V2, post_settlement_root),
            (STATEMENT_DECLARED_WORK_INDEX_V2, declared_work.digest()),
            (STATEMENT_PRE_UNIQUENESS_INDEX_V2, context.digest()),
            (
                STATEMENT_SPENT_PRECOMMIT_INDEX_V2,
                challenge[65..97].try_into().unwrap(),
            ),
            (
                STATEMENT_OUTPUT_PRECOMMIT_INDEX_V2,
                challenge[97..129].try_into().unwrap(),
            ),
        ] {
            let start = TRANSITION_DIGESTS_OFFSET_V2 + index * 32;
            statement[start..start + 32].copy_from_slice(&digest);
        }
        if missing_job {
            let remove = events
                .iter()
                .position(|event| {
                    decode_hash_control(event)
                        .map(|control| {
                            control.schema == HashControlSchemaV2::UniquenessTranscript
                                && control.stage == HashControlStageV2::End
                                && control.uniqueness_transcript.map(|binding| binding.job)
                                    == Some(UniquenessTranscriptHashJobV2::OutputPair1Beta)
                        })
                        .unwrap_or(false)
                })
                .unwrap();
            events.remove(remove);
        }
        (encode_event_vector(&events), statement)
    }

    fn base_statement_bytes_for_test() -> Vec<u8> {
        let mut statement = vec![0; PLONKY3_BASE_STATEMENT_BYTES_V2];
        statement[..PLONKY3_STATEMENT_MAGIC_V2.len()].copy_from_slice(&PLONKY3_STATEMENT_MAGIC_V2);
        statement[PLONKY3_STATEMENT_MAGIC_V2.len()..PLONKY3_STATEMENT_MAGIC_V2.len() + 2]
            .copy_from_slice(&PLONKY3_BASE_WIRE_VERSION_V2.to_le_bytes());
        for (index, digest) in [(0, [6; 32]), (1, [7; 32]), (7, [3; 32]), (8, [4; 32])] {
            let start = PLONKY3_STATEMENT_DIGESTS_OFFSET_V2 + index * 32;
            statement[start..start + 32].copy_from_slice(&digest);
        }
        statement
    }

    fn predicate_words_for_test(event_vector: &[u8]) -> Vec<u16> {
        let statement = base_statement_bytes_for_test();
        predicate_words_with_statement(event_vector, &statement)
    }

    fn predicate_words_with_statement(event_vector: &[u8], statement: &[u8]) -> Vec<u16> {
        assert_eq!(statement.len(), PLONKY3_BASE_STATEMENT_BYTES_V2);
        let mut bytes = Vec::new();
        bytes.extend_from_slice(PLONKY3_PREDICATE_VECTOR_LABEL_V2);
        bytes.extend_from_slice(
            &u64::try_from(PLONKY3_BASE_STATEMENT_BYTES_V2)
                .expect("fixed statement size")
                .to_le_bytes(),
        );
        bytes.extend_from_slice(statement);
        bytes.extend_from_slice(
            &u64::try_from(event_vector.len())
                .expect("fixture vector size")
                .to_le_bytes(),
        );
        bytes.extend_from_slice(event_vector);
        while bytes.len() % 16 != 0 {
            bytes.push(0);
        }
        bytes
            .chunks_exact(2)
            .map(|pair| u16::from_le_bytes([pair[0], pair[1]]))
            .collect()
    }

    fn run_prepared(prepared: PreparedRunnerV2) -> Result<(), CheckpointError> {
        let PreparedRunnerV2 {
            circuit,
            private_inputs,
        } = prepared;
        let mut runner = circuit.runner();
        runner
            .set_private_inputs(&private_inputs)
            .map_err(|_| CheckpointError::Invariant)?;
        drop(private_inputs);
        runner
            .run()
            .map(|_| ())
            .map_err(|_| CheckpointError::BackendVerificationFailed)
    }

    #[test]
    fn test_security_budget_rounding() {
        let manifest = RecursiveSecurityBudgetManifestV2::authority_pinned().unwrap();
        assert_eq!(
            manifest.per_proof_bound.denominator_exponent(),
            PER_PROOF_BOUND_BITS_V2
        );
        assert_eq!(
            manifest.max_accepted_epoch_proofs,
            MAX_ACCEPTED_EPOCH_PROOFS_V2
        );
        assert!(manifest.lifetime_residual_bits() >= PLONKY3_MINIMUM_RESIDUAL_BITS_V2);
        assert_ne!(manifest.digest(), [0; 32]);
    }

    #[test]
    fn test_security_derivation_rejects_drift() {
        assert_eq!(ceil_log2_terms(1).unwrap(), 0);
        assert_eq!(ceil_log2_terms(3).unwrap(), 2);
        assert_eq!(ceil_log2_terms(1 << 20).unwrap(), 20);
        assert_eq!(ceil_log2_terms((1 << 20) + 1).unwrap(), 21);
        assert_eq!(
            derive_replica_tree_bound(
                FRI_PHYSICAL_QUANTUM_BITS_V2,
                HASH_QUANTUM_COLLISION_BITS_V2,
                PHYSICAL_CHALLENGER_PREIMAGE_BITS_V2,
                PLONKY3_FRI_REPLICA_COUNT_V2,
                PLONKY3_LOGICAL_NODE_COUNT_V2,
                3,
            )
            .unwrap()
            .denominator_exponent(),
            PER_PROOF_BOUND_BITS_V2
        );
        assert_eq!(
            derive_per_proof_bound(
                FRI_QUANTUM_SEARCH_BITS_V2,
                HASH_QUANTUM_COLLISION_BITS_V2 - 17,
                CHALLENGER_QUANTUM_PREIMAGE_BITS_V2,
                3,
            )
            .unwrap()
            .denominator_exponent(),
            133
        );
        assert_eq!(
            derive_lifetime_bound(
                DyadicErrorBoundV2::new(PER_PROOF_BOUND_BITS_V2).unwrap(),
                1 << 20,
                DyadicErrorBoundV2::new(128).unwrap(),
            )
            .unwrap()
            .denominator_exponent(),
            107
        );
        assert!(derive_replica_tree_bound(
            FRI_PHYSICAL_QUANTUM_BITS_V2,
            HASH_QUANTUM_COLLISION_BITS_V2,
            PHYSICAL_CHALLENGER_PREIMAGE_BITS_V2,
            0,
            PLONKY3_LOGICAL_NODE_COUNT_V2,
            0,
        )
        .is_err());
        assert!(derive_lifetime_bound(
            DyadicErrorBoundV2::new(PER_PROOF_BOUND_BITS_V2).unwrap(),
            0,
            DyadicErrorBoundV2::new(128).unwrap(),
        )
        .is_err());
        assert!(matches!(
            derive_lifetime_bound(
                DyadicErrorBoundV2::new(PER_PROOF_BOUND_BITS_V2).unwrap(),
                u64::MAX,
                DyadicErrorBoundV2::new(128).unwrap(),
            ),
            Err(CheckpointError::Overflow)
        ));

        let baseline = RecursiveSecurityBudgetManifestV2::authority_pinned().unwrap();
        let mutations: Vec<fn(&mut RecursiveSecurityBudgetManifestV2)> = vec![
            |value| value.generation += 1,
            |value| value.parameter_generation += 1,
            |value| value.base_field_bits -= 1,
            |value| value.challenge_extension_degree -= 1,
            |value| value.fri_log_blowup += 1,
            |value| value.fri_num_queries -= 1,
            |value| value.fri_commit_pow_bits += 1,
            |value| value.fri_query_pow_bits += 1,
            |value| value.fri_replica_count -= 1,
            |value| value.fri_physical_classical_bits -= 1,
            |value| value.fri_physical_quantum_search_bits -= 1,
            |value| value.fri_classical_bits -= 1,
            |value| value.fri_quantum_search_bits -= 1,
            |value| value.hash_output_bits -= 1,
            |value| value.hash_collision_bits -= 1,
            |value| value.challenger_capacity_bits -= 1,
            |value| value.challenger_physical_quantum_preimage_bits -= 1,
            |value| value.challenger_quantum_preimage_bits -= 1,
            |value| value.component_count = 0,
            |value| value.recursion_depth += 1,
            |value| value.logical_leaf_count -= 1,
            |value| value.logical_node_count -= 1,
            |value| value.composition_rule_generation += 1,
            |value| value.per_proof_bound = DyadicErrorBoundV2::new(127).unwrap(),
            |value| value.max_accepted_epoch_proofs = 0,
            |value| value.max_accepted_epoch_proofs = u64::MAX,
            |value| value.inherited_bound = None,
            |value| value.lifetime_bound = DyadicErrorBoundV2::new(99).unwrap(),
            |value| value.minimum_residual_bits = 106,
        ];
        for mutate in mutations {
            let mut changed = baseline.clone();
            mutate(&mut changed);
            assert!(changed.validate().is_err());
        }
    }

    #[test]
    fn test_poseidon_hash_binds_shape() {
        let a = vec![1_u16, 2, 3, 4, 5, 6, 7, 8];
        let mut b = a.clone();
        b.swap(1, 2);
        assert_ne!(poseidon_vector_hash(&a), poseidon_vector_hash(&b));
        b.push(0);
        while b.len() % 8 != 0 {
            b.push(0);
        }
        assert_ne!(poseidon_vector_hash(&a), poseidon_vector_hash(&b));
    }

    #[test]
    fn test_statement_values_share_common() {
        let chunk = AirChunkV2::singleton(AirDomainV2::Full);
        let words_a = [1_u16, 2, 3, 4, 5, 6, 7, 8];
        let words_b = [8_u16, 7, 6, 5, 4, 3, 2, 1];
        let statement_a = root_statement_fixture(&words_a, None, chunk).unwrap();
        let statement_b = RootStatementV2::leaf(
            [9; 32],
            [8; 32],
            [7; 32],
            [6; 32],
            [5; 32],
            chunk_commitment(&words_b, None, chunk).unwrap(),
            0,
            0,
            1,
        )
        .unwrap();
        assert_ne!(statement_a.values(), statement_b.values());
        assert_ne!(statement_a.commitment(), statement_b.commitment());

        let prepared_a = prepare_circuit(&words_a, None, chunk, &statement_a).unwrap();
        let prepared_b = prepare_circuit(&words_b, None, chunk, &statement_b).unwrap();
        assert_eq!(
            common_binding_digest(prepared_a.data.common_data()).unwrap(),
            common_binding_digest(prepared_b.data.common_data()).unwrap(),
            "statement and leaf values must not change the verifier common data"
        );

        let wrong_statement = RootStatementV2::leaf(
            [9; 32],
            [8; 32],
            [7; 32],
            [6; 32],
            [5; 32],
            statement_a.commitment(),
            0,
            0,
            1,
        )
        .unwrap();
        assert!(prepare_circuit(&words_b, None, chunk, &wrong_statement).is_err());
    }

    #[test]
    fn test_recursive_common_ignores_values() {
        let chunk = AirChunkV2::singleton(AirDomainV2::Full);
        let make_statement = |words: &[u16], mark: u8, start: u16| {
            RootStatementV2::leaf(
                [mark; 32],
                [mark.wrapping_add(1); 32],
                [mark.wrapping_add(2); 32],
                [mark.wrapping_add(3); 32],
                [mark.wrapping_add(4); 32],
                chunk_commitment(words, None, chunk).unwrap(),
                0,
                start,
                2,
            )
            .unwrap()
        };
        let words_a = [1_u16, 2, 3, 4, 5, 6, 7, 8];
        let words_b = [8_u16, 7, 6, 5, 4, 3, 2, 1];
        let a_left = prove_small_batch(&words_a, &make_statement(&words_a, 1, 0)).unwrap();
        let a_right = prove_small_batch(&words_a, &make_statement(&words_a, 1, 1)).unwrap();
        let b_left = prove_small_batch(&words_b, &make_statement(&words_b, 17, 0)).unwrap();
        let b_right = prove_small_batch(&words_b, &make_statement(&words_b, 17, 1)).unwrap();

        let config = hardened_koala_bear_config();
        let backend = BoundRecursionBackendV2;
        let a_left_input = batch_recursion_input(&a_left).unwrap();
        let a_right_input = batch_recursion_input(&a_right).unwrap();
        let b_left_input = batch_recursion_input(&b_left).unwrap();
        let b_right_input = batch_recursion_input(&b_right).unwrap();
        let (a_circuit, _) = build_bound_aggregation_circuit(
            &a_left_input,
            &a_right_input,
            &config,
            &backend,
            AggregationRelationV2::LeafRange,
        )
        .unwrap();
        let (b_circuit, _) = build_bound_aggregation_circuit(
            &b_left_input,
            &b_right_input,
            &config,
            &backend,
            AggregationRelationV2::LeafRange,
        )
        .unwrap();
        assert_eq!(
            aggregation_common_for_test(&a_circuit).unwrap(),
            aggregation_common_for_test(&b_circuit).unwrap(),
            "recursive verifier common must depend on shape, not statement values"
        );
    }

    #[test]
    fn test_common_cap_native_order() {
        let words = [0_u16, u16::MAX, 1, 2, 3, 4, 5, 6];
        let chunk = AirChunkV2::singleton(AirDomainV2::Full);
        let statement = root_statement_fixture(&words, None, chunk).unwrap();
        let prepared = prepare_circuit(&words, None, chunk, &statement).unwrap();
        let common = prepared.data.common_data();
        let common_fields = common_target_fields(common).unwrap();
        let common_cap = common_cap_fields(common).unwrap();
        assert_eq!(common_fields.len(), ROOT_COMMON_CAP_FIELDS_V2);
        assert_eq!(common_cap.as_slice(), common_fields.as_slice());
    }

    #[test]
    fn test_common_cap_rejects_alias() {
        let words = [0_u16, u16::MAX, 1, 2, 3, 4, 5, 6];
        let chunk = AirChunkV2::singleton(AirDomainV2::Full);
        let statement = root_statement_fixture(&words, None, chunk).unwrap();
        let mut builder = CircuitBuilder::new();
        BoundRecursionBackendV2
            .prepare_circuit(&hardened_koala_bear_config(), &mut builder)
            .unwrap();
        let targets =
            builder.alloc_public_inputs(ROOT_STATEMENT_FIELDS_V2, "root statement alias gate");
        bind_root_statement_targets(&mut builder, &targets).unwrap();
        let circuit = builder.build().unwrap();
        let canonical = statement
            .values()
            .iter()
            .copied()
            .map(lift_koala)
            .collect::<Vec<_>>();
        let mut runner = circuit.runner();
        runner.set_public_inputs(&canonical).unwrap();
        runner.run().unwrap();

        let mut aliased = canonical;
        aliased[ROOT_COMMON_CAP_INDEX_V2] = Plonky3ChallengeV2::new([
            KoalaBear::ZERO,
            KoalaBear::ONE,
            KoalaBear::ZERO,
            KoalaBear::ZERO,
        ]);
        let mut runner = circuit.runner();
        runner.set_public_inputs(&aliased).unwrap();
        assert!(
            runner.run().is_err(),
            "common-cap fields must be canonical base-field embeddings",
        );
    }

    #[test]
    fn test_recursive_event_source_framing_rejects_public_aliases() {
        use plonky3_epoch_event_source_columns as event_source;
        use plonky3_epoch_transition_air as transition;

        const EVENT_BYTES: u16 = 1_000;

        let mut builder = CircuitBuilder::new();
        register_u16_range_npo(&mut builder);
        let transition_targets =
            builder.alloc_public_inputs(transition::PUBLIC_FIELDS_V2, "transition public");
        let event_targets =
            builder.alloc_public_inputs(event_source::PUBLIC_FIELDS_V2, "event-source public");
        constrain_canonical_event_source_framing(
            &mut builder,
            &transition_targets,
            &event_targets,
            1,
            0,
            1,
        )
        .unwrap();
        let circuit = builder.build().unwrap();

        let mut transition_public = vec![Plonky3ChallengeV2::ZERO; transition::PUBLIC_FIELDS_V2];
        let binding = direct_binding_range(0).unwrap();
        transition_public[binding.start + transition::BINDING_EVENT_BYTES_OFFSET_V2] =
            lift_koala(KoalaBear::from_u16(EVENT_BYTES));

        let mut event_public = vec![Plonky3ChallengeV2::ZERO; event_source::PUBLIC_FIELDS_V2];
        event_public[event_source::PUBLIC_ACTIVE_OFFSET_V2] =
            lift_koala(KoalaBear::from_bool(true));
        event_public[event_source::PUBLIC_EVENT_BYTES_OFFSET_V2] =
            lift_koala(KoalaBear::from_u16(EVENT_BYTES));
        event_public[event_source::PUBLIC_SLICE_LEN_OFFSET_V2] = lift_koala(KoalaBear::from_u8(1));
        let prefix =
            CheckpointSha256BlockStreamV2::framed_role_prefix(CheckpointShaRole::EventVector);
        for (pair, bytes) in prefix.chunks_exact(2).enumerate() {
            event_public[event_source::PUBLIC_STATIC_PREFIX_OFFSET_V2 + pair] =
                lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                    bytes[0], bytes[1],
                ])));
        }
        for (pair, bytes) in EVENT_BYTES.to_le_bytes().chunks_exact(2).enumerate() {
            event_public[event_source::PUBLIC_PART_LENGTH_OFFSET_V2 + pair] =
                lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                    bytes[0], bytes[1],
                ])));
        }
        let framed_bytes = CheckpointSha256BlockStreamV2::framed_bytes_for_parts(
            CheckpointShaRole::EventVector,
            u64::from(EVENT_BYTES),
            1,
        )
        .unwrap();
        for (pair, bytes) in framed_bytes
            .checked_mul(8)
            .unwrap()
            .to_be_bytes()
            .chunks_exact(2)
            .enumerate()
        {
            event_public[event_source::PUBLIC_BIT_LENGTH_OFFSET_V2 + pair] =
                lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                    bytes[0], bytes[1],
                ])));
        }
        let block_count =
            CheckpointSha256BlockStreamV2::block_count_for_framed_bytes(framed_bytes).unwrap();
        event_public[event_source::PUBLIC_BLOCK_COUNT_OFFSET_V2] =
            lift_koala(KoalaBear::from_u64(block_count));

        let run = |event_public: &[Plonky3ChallengeV2]| {
            let public_inputs = transition_public
                .iter()
                .chain(event_public)
                .copied()
                .collect::<Vec<_>>();
            let mut runner = circuit.runner();
            runner.set_public_inputs(&public_inputs).unwrap();
            runner.run()
        };
        run(&event_public).unwrap();

        for field in [
            event_source::PUBLIC_STATIC_PREFIX_OFFSET_V2,
            event_source::PUBLIC_PART_LENGTH_OFFSET_V2,
            event_source::PUBLIC_BIT_LENGTH_OFFSET_V2 + event_source::LENGTH_PAIRS_V2 - 1,
            event_source::PUBLIC_BLOCK_COUNT_OFFSET_V2,
        ] {
            let mut aliased = event_public.clone();
            aliased[field] = Plonky3ChallengeV2::ZERO;
            assert!(
                run(&aliased).is_err(),
                "recursive framing must reject aliased event-source field {field}",
            );
        }
    }

    #[test]
    fn test_recursive_upper_slice_framing_rejects_global_slot_mutation() {
        use plonky3_epoch_event_source_columns as event_source;
        use plonky3_epoch_transition_air as transition;

        const ACTIVE_COUNT: usize = 8;
        const UPPER_SLICE_START: usize = 4;
        const UPPER_SLICE_LEN: usize = 4;

        let mut builder = CircuitBuilder::new();
        register_u16_range_npo(&mut builder);
        let transition_targets =
            builder.alloc_public_inputs(transition::PUBLIC_FIELDS_V2, "transition public");
        let event_targets =
            builder.alloc_public_inputs(event_source::PUBLIC_FIELDS_V2, "event-source public");
        constrain_canonical_event_source_framing(
            &mut builder,
            &transition_targets,
            &event_targets,
            ACTIVE_COUNT,
            UPPER_SLICE_START,
            UPPER_SLICE_LEN,
        )
        .unwrap();
        let circuit = builder.build().unwrap();

        let mut transition_public = vec![Plonky3ChallengeV2::ZERO; transition::PUBLIC_FIELDS_V2];
        let mut event_public = vec![Plonky3ChallengeV2::ZERO; event_source::PUBLIC_FIELDS_V2];
        let prefix =
            CheckpointSha256BlockStreamV2::framed_role_prefix(CheckpointShaRole::EventVector);
        for (pair, bytes) in prefix.chunks_exact(2).enumerate() {
            event_public[event_source::PUBLIC_STATIC_PREFIX_OFFSET_V2 + pair] =
                lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                    bytes[0], bytes[1],
                ])));
        }
        event_public[event_source::PUBLIC_SLICE_START_OFFSET_V2] =
            lift_koala(KoalaBear::from_usize(UPPER_SLICE_START));
        event_public[event_source::PUBLIC_SLICE_LEN_OFFSET_V2] =
            lift_koala(KoalaBear::from_usize(UPPER_SLICE_LEN));

        let set_framed_lane =
            |public: &mut [Plonky3ChallengeV2], local_slot: usize, event_bytes: u16| {
                public[event_source::PUBLIC_ACTIVE_OFFSET_V2 + local_slot] =
                    lift_koala(KoalaBear::from_bool(true));
                public[event_source::PUBLIC_EVENT_BYTES_OFFSET_V2 + local_slot] =
                    lift_koala(KoalaBear::from_u16(event_bytes));
                for (pair, bytes) in event_bytes.to_le_bytes().chunks_exact(2).enumerate() {
                    public[event_source::PUBLIC_PART_LENGTH_OFFSET_V2
                        + local_slot * event_source::LENGTH_PAIRS_V2
                        + pair] = lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                        bytes[0], bytes[1],
                    ])));
                }
                let framed_bytes = CheckpointSha256BlockStreamV2::framed_bytes_for_parts(
                    CheckpointShaRole::EventVector,
                    u64::from(event_bytes),
                    1,
                )
                .unwrap();
                for (pair, bytes) in framed_bytes
                    .checked_mul(8)
                    .unwrap()
                    .to_be_bytes()
                    .chunks_exact(2)
                    .enumerate()
                {
                    public[event_source::PUBLIC_BIT_LENGTH_OFFSET_V2
                        + local_slot * event_source::LENGTH_PAIRS_V2
                        + pair] = lift_koala(KoalaBear::from_u16(u16::from_be_bytes([
                        bytes[0], bytes[1],
                    ])));
                }
                public[event_source::PUBLIC_BLOCK_COUNT_OFFSET_V2 + local_slot] =
                    lift_koala(KoalaBear::from_u64(
                        CheckpointSha256BlockStreamV2::block_count_for_framed_bytes(framed_bytes)
                            .unwrap(),
                    ));
            };

        for local_slot in 0..UPPER_SLICE_LEN {
            let event_bytes = 1_000_u16 + u16::try_from(local_slot).unwrap();
            let binding = direct_binding_range(UPPER_SLICE_START + local_slot).unwrap();
            transition_public[binding.start + transition::BINDING_EVENT_BYTES_OFFSET_V2] =
                lift_koala(KoalaBear::from_u16(event_bytes));
            set_framed_lane(&mut event_public, local_slot, event_bytes);
        }

        let run = |event_public: &[Plonky3ChallengeV2]| {
            let public_inputs = transition_public
                .iter()
                .chain(event_public)
                .copied()
                .collect::<Vec<_>>();
            let mut runner = circuit.runner();
            runner.set_public_inputs(&public_inputs).unwrap();
            runner.run()
        };
        run(&event_public).unwrap();

        let mut forged_global_slot = event_public.clone();
        set_framed_lane(&mut forged_global_slot, 0, 777);
        assert!(
            run(&forged_global_slot).is_err(),
            "upper-slice framing must bind local lane zero to global slot four, not slot zero",
        );

        let mut forged_descriptor = event_public.clone();
        forged_descriptor[event_source::PUBLIC_SLICE_START_OFFSET_V2] = Plonky3ChallengeV2::ZERO;
        assert!(
            run(&forged_descriptor).is_err(),
            "upper-slice framing must reject a forged global slice descriptor",
        );
    }

    #[test]
    fn test_pair_hash_binds_order() {
        let left = [KoalaBear::from_u8(1); ROOT_STATEMENT_COMMITMENT_FIELDS_V2];
        let right = [KoalaBear::from_u8(2); ROOT_STATEMENT_COMMITMENT_FIELDS_V2];
        assert_ne!(
            poseidon_pair_hash(left, right),
            poseidon_pair_hash(right, left)
        );
        assert_ne!(
            poseidon_pair_hash(left, right),
            poseidon_pair_hash_for_domain(left, right, RootCommitmentDomainV2::FirstReplicaFold,),
            "leaf-range and replica-fold commitments require separate domains"
        );
        assert_ne!(
            poseidon_pair_hash_for_domain(left, right, RootCommitmentDomainV2::FirstReplicaFold,),
            poseidon_pair_hash_for_domain(left, right, RootCommitmentDomainV2::FinalReplicaFold,),
            "the two ordered replica-fold stages require separate domains"
        );
        assert_ne!(
            poseidon_pair_hash_for_domain(left, right, RootCommitmentDomainV2::EpochRange),
            poseidon_pair_hash(left, right),
            "epoch ranges must not reuse the base AIR leaf-tree domain"
        );
    }

    #[test]
    fn test_direct_trace_chunk_normalization_and_range_binding() {
        use crate::checkpoint::epoch_frontier::{
            EpochFrontierAuthorityInputsV2, EpochFrontierAuthorityV2,
        };
        use crate::checkpoint::EpochCadenceClassV2;

        const TOTAL_TRANSITIONS: u32 = 16;
        let chain_context_digest = [0xc1; 32];
        let predicate_digest = [0xc2; 32];
        let start_root = [0xe0; 32];
        let history = Plonky3HistoryAuthorityResolverV2::resolve_active().unwrap();
        let identity = history.identity();
        let authority = EpochFrontierAuthorityV2::new(EpochFrontierAuthorityInputsV2 {
            cadence_class: EpochCadenceClassV2::BoundedSimulation,
            epoch_index: 0,
            cadence_blocks: u64::from(TOTAL_TRANSITIONS),
            start_root,
            chain_context_digest,
            predicate_digest,
            parameter_digest: identity.verifier_parameter_digest,
            verifier_bundle_digest: identity.verifier_bundle_digest,
        })
        .unwrap();
        let digest = |label: &str, ordinal: u32| {
            sha256_256(
                "z00z.storage.checkpoint.plonky3.direct-chunk-normalization.tests.v2",
                label,
                &[&ordinal.to_le_bytes()],
            )
        };
        let checkpoint_ids = (0..TOTAL_TRANSITIONS)
            .map(|ordinal| digest("checkpoint_id", ordinal))
            .collect::<Vec<_>>();
        let state_roots = (0..=TOTAL_TRANSITIONS)
            .map(|ordinal| {
                if ordinal == 0 {
                    start_root
                } else {
                    digest("state_root", ordinal)
                }
            })
            .collect::<Vec<_>>();
        let bindings = (0..TOTAL_TRANSITIONS)
            .map(|ordinal| {
                let index = usize::try_from(ordinal).unwrap();
                EpochTransitionBindingV2::new(EpochTransitionInputsV2 {
                    ordinal,
                    height: u64::from(ordinal) + 1,
                    checkpoint_id: checkpoint_ids[index],
                    predecessor: ordinal
                        .checked_sub(1)
                        .map(|previous| checkpoint_ids[usize::try_from(previous).unwrap()]),
                    recursive_transition_statement_digest: digest("recursive_statement", ordinal),
                    checkpoint_exec_tx_root: digest("exec_tx_root", ordinal),
                    checkpoint_exec_tx_count: 1,
                    checkpoint_statement_digest: digest("statement", ordinal),
                    checkpoint_statement_core_digest: digest("statement_core", ordinal),
                    checkpoint_link_digest: digest("link", ordinal),
                    checkpoint_artifact_digest: digest("artifact", ordinal),
                    delta_root: digest("delta", ordinal),
                    witness_root: digest("witness", ordinal),
                    journal_digest: digest("journal", ordinal),
                    challenge_content_digest: digest("challenge", ordinal),
                    da_payload_commitment: digest("da", ordinal),
                    prior_recursive_output_root: ordinal
                        .checked_sub(1)
                        .map(|_| digest("prior_ivc", ordinal)),
                    pre_settlement_root: state_roots[index],
                    post_settlement_root: state_roots[index + 1],
                    pre_definition_root: digest("definition_pre", ordinal),
                    post_definition_root: digest("definition_post", ordinal),
                    trace_digest: digest("trace", ordinal),
                    update_trace_digest: digest("update_trace", ordinal),
                    declared_work_digest: digest("declared_work", ordinal),
                    pre_uniqueness_context_digest: digest("pre_uniqueness", ordinal),
                    spent_uniqueness_precommit: digest("spent_precommit", ordinal),
                    output_uniqueness_precommit: digest("output_precommit", ordinal),
                    event_vector_digest: digest("events", ordinal),
                    event_count: 3,
                    event_bytes: 1,
                    uniqueness_row_count: 1,
                    jmt_record_count: 1,
                    jmt_envelope_count: 1,
                    jmt_update_count: 1,
                })
                .unwrap()
            })
            .collect::<Vec<_>>();
        let make_chunk = |chunk_ordinal: u32| {
            let first = chunk_ordinal * EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2;
            let last = first + EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2 - 1;
            let chunk_bindings =
                bindings[usize::try_from(first).unwrap()..=usize::try_from(last).unwrap()].to_vec();
            let transition_digests = chunk_bindings
                .iter()
                .map(EpochTransitionBindingV2::digest)
                .collect::<Vec<_>>();
            let input_slice_commitment =
                crate::checkpoint::epoch_range::epoch_ordered_digest_root_v2(
                    crate::checkpoint::epoch_prover::EPOCH_TRANSITION_SLICE_DOMAIN_V2,
                    &transition_digests,
                )
                .unwrap();
            let input_accumulator = bindings[..usize::try_from(first).unwrap()]
                .iter()
                .copied()
                .fold(
                    crate::checkpoint::epoch_prover::epoch_stream_initial_accumulator(authority),
                    |accumulator, transition| {
                        crate::checkpoint::epoch_prover::epoch_stream_step_accumulator(
                            authority,
                            accumulator,
                            transition,
                        )
                    },
                );
            let output_accumulator = chunk_bindings.iter().copied().fold(
                input_accumulator,
                |accumulator, transition| {
                    crate::checkpoint::epoch_prover::epoch_stream_step_accumulator(
                        authority,
                        accumulator,
                        transition,
                    )
                },
            );
            let statement = EpochTraceChunkV2::new(
                &authority,
                &chunk_bindings,
                EpochTraceChunkInputsV2 {
                    table: EpochAirTableV2::Transition,
                    replica: 0,
                    chunk_ordinal,
                    chunk_count: authority.chunk_count(),
                    first_transition: first,
                    last_transition: last,
                    transition_count: TOTAL_TRANSITIONS,
                    row_start: 0,
                    row_count: u64::try_from(plonky3_epoch_transition_air::ROWS_V2).unwrap(),
                    event_start: u64::from(first) * 3,
                    event_count: u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2) * 3,
                    frontier_authority_digest: authority.digest(),
                    chain_context_digest,
                    predicate_digest,
                    input_state_root: state_roots[usize::try_from(first).unwrap()],
                    output_state_root: state_roots[usize::try_from(last + 1).unwrap()],
                    input_accumulator,
                    output_accumulator,
                    input_slice_commitment,
                    parameter_digest: authority.parameter_digest(),
                    verifier_bundle_digest: authority.verifier_bundle_digest(),
                    security_budget_digest: authority.security_budget_digest(),
                },
            )
            .unwrap();
            EpochTraceChunkProofInputsV2 {
                chunk_ordinal,
                statement,
                bindings: chunk_bindings,
            }
        };
        let left_chunk = make_chunk(0);
        let right_chunk = make_chunk(1);
        let pair = EpochChunkPairInputsV2 {
            left: left_chunk.clone(),
            right: right_chunk.clone(),
            total_transition_count: TOTAL_TRANSITIONS,
            total_chunk_count: authority.chunk_count(),
            epoch_index: authority.epoch_index(),
            cadence_blocks: authority.cadence_blocks(),
            parameter_generation: authority.parameter_generation(),
            runtime_profile_generation: authority.runtime_profile_generation(),
        };
        let child_common = [KoalaBear::from_u8(7); ROOT_COMMON_CAP_FIELDS_V2];
        let parent_common = [KoalaBear::from_u8(8); ROOT_COMMON_CAP_FIELDS_V2];
        let typed_common = [KoalaBear::from_u8(9); ROOT_COMMON_CAP_FIELDS_V2];
        let jmt_common = [KoalaBear::from_u8(10); ROOT_COMMON_CAP_FIELDS_V2];
        let flow_common = [KoalaBear::from_u8(11); ROOT_COMMON_CAP_FIELDS_V2];
        let hash_common = [KoalaBear::from_u8(12); ROOT_COMMON_CAP_FIELDS_V2];
        let uniqueness_lower_common = [KoalaBear::from_u8(13); ROOT_COMMON_CAP_FIELDS_V2];
        let uniqueness_upper_common = [KoalaBear::from_u8(14); ROOT_COMMON_CAP_FIELDS_V2];
        let complete_common = [KoalaBear::from_u8(15); ROOT_COMMON_CAP_FIELDS_V2];
        let normalize = |chunk: &EpochTraceChunkProofInputsV2| {
            let direct_public =
                plonky3_epoch_transition_witness::public_values(&chunk.statement, &chunk.bindings)
                    .unwrap();
            let transition = normalized_epoch_chunk_statement_values(
                &direct_public,
                child_common,
                &EpochChunkNormalizationInputsV2::from_pair(&pair, chunk),
                parent_common,
            )
            .unwrap();
            let typed = epoch_chunk_coverage_statement_values(
                &transition,
                EPOCH_CHUNK_TRANSITION_COVERAGE_V2,
                EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2,
                typed_common,
            )
            .unwrap();
            let jmt = epoch_chunk_coverage_statement_values(
                &typed,
                EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2,
                EPOCH_CHUNK_TRANSITION_JMT_COVERAGE_V2,
                jmt_common,
            )
            .unwrap();
            let flow = epoch_chunk_coverage_statement_values(
                &jmt,
                EPOCH_CHUNK_TRANSITION_JMT_COVERAGE_V2,
                EPOCH_CHUNK_TRANSITION_FLOW_COVERAGE_V2,
                flow_common,
            )
            .unwrap();
            let hash = epoch_chunk_coverage_statement_values(
                &flow,
                EPOCH_CHUNK_TRANSITION_FLOW_COVERAGE_V2,
                EPOCH_CHUNK_HASH_COVERAGE_V2,
                hash_common,
            )
            .unwrap();
            let uniqueness_lower = epoch_chunk_coverage_statement_values(
                &hash,
                EPOCH_CHUNK_HASH_COVERAGE_V2,
                EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
                uniqueness_lower_common,
            )
            .unwrap();
            epoch_chunk_coverage_statement_values(
                &uniqueness_lower,
                EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
                EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
                uniqueness_upper_common,
            )
            .and_then(|complete| {
                epoch_chunk_coverage_statement_values(
                    &complete,
                    EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
                    EPOCH_RANGE_FOLD_ORDINAL_V2,
                    complete_common,
                )
            })
            .unwrap()
        };
        let normalized_left = normalize(&pair.left);
        let normalized_right = normalize(&pair.right);
        assert_eq!(
            normalized_left[ROOT_STATEMENT_START_INDEX_V2].as_canonical_u64(),
            0
        );
        assert_eq!(
            normalized_left[ROOT_STATEMENT_COUNT_INDEX_V2].as_canonical_u64(),
            u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2)
        );
        assert_eq!(
            normalized_right[ROOT_STATEMENT_START_INDEX_V2].as_canonical_u64(),
            u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2)
        );
        assert_eq!(
            root_statement_digest(&normalized_left, ROOT_DIGEST_RANGE_START_ACCUMULATOR_V2,)
                .unwrap(),
            pair.left.statement.inputs().input_accumulator,
        );
        assert_eq!(
            root_statement_digest(&normalized_left, ROOT_DIGEST_RANGE_END_ACCUMULATOR_V2,).unwrap(),
            pair.left.statement.inputs().output_accumulator,
        );
        let combined = combine_root_values_for_relation(
            &normalized_left,
            &normalized_right,
            AggregationRelationV2::EpochRange,
        )
        .unwrap();
        assert_eq!(
            combined[ROOT_STATEMENT_COUNT_INDEX_V2].as_canonical_u64(),
            u64::from(TOTAL_TRANSITIONS)
        );
        let all_statements = bindings
            .iter()
            .map(|binding| binding.inputs().checkpoint_statement_digest)
            .collect::<Vec<_>>();
        assert_eq!(
            root_statement_digest(&combined, ROOT_DIGEST_STATEMENT_TREE_V2).unwrap(),
            epoch_ordered_digest_subtree_v2(
                EPOCH_STATEMENT_ROOT_DOMAIN_V2,
                u64::from(TOTAL_TRANSITIONS),
                0,
                &all_statements,
            )
            .unwrap()
        );
        let left_span =
            root_statement_digest(&normalized_left, ROOT_DIGEST_VERIFIED_TRACE_CHUNK_TREE_V2)
                .unwrap();
        let right_span =
            root_statement_digest(&normalized_right, ROOT_DIGEST_VERIFIED_TRACE_CHUNK_TREE_V2)
                .unwrap();
        assert_eq!(
            root_statement_digest(&combined, ROOT_DIGEST_VERIFIED_TRACE_CHUNK_TREE_V2).unwrap(),
            epoch_ordered_digest_parent_v2(
                EPOCH_VERIFIED_TRACE_CHUNK_ROOT_DOMAIN_V2,
                u64::from(TOTAL_TRANSITIONS),
                0,
                u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2),
                u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2),
                u64::from(EPOCH_TRANSITIONS_PER_TRACE_CHUNK_V2),
                left_span,
                right_span,
            )
            .unwrap()
        );
        let mut substituted = plonky3_epoch_transition_witness::public_values(
            &pair.right.statement,
            &pair.right.bindings,
        )
        .unwrap();
        substituted[direct_binding_digest_range(
            0,
            plonky3_epoch_transition_air::BINDING_DIGEST_OFFSET_V2,
        )
        .unwrap()
        .start] += KoalaBear::ONE;
        assert!(normalized_epoch_chunk_statement_values(
            &substituted,
            child_common,
            &EpochChunkNormalizationInputsV2::from_pair(&pair, &pair.right),
            parent_common,
        )
        .is_err());
    }

    #[test]
    fn test_epoch_chunk_coverage_is_sequential_and_fail_closed() {
        let mut transition = vec![KoalaBear::ZERO; ROOT_STATEMENT_FIELDS_V2];
        transition[ROOT_STATEMENT_REPLICA_INDEX_V2] =
            KoalaBear::from_u8(EPOCH_CHUNK_TRANSITION_COVERAGE_V2);
        let typed_common = [KoalaBear::from_u8(1); ROOT_COMMON_CAP_FIELDS_V2];
        let jmt_common = [KoalaBear::from_u8(2); ROOT_COMMON_CAP_FIELDS_V2];
        let flow_common = [KoalaBear::from_u8(3); ROOT_COMMON_CAP_FIELDS_V2];
        let hash_common = [KoalaBear::from_u8(4); ROOT_COMMON_CAP_FIELDS_V2];
        let uniqueness_lower_common = [KoalaBear::from_u8(5); ROOT_COMMON_CAP_FIELDS_V2];
        let complete_common = [KoalaBear::from_u8(6); ROOT_COMMON_CAP_FIELDS_V2];

        let typed = epoch_chunk_coverage_statement_values(
            &transition,
            EPOCH_CHUNK_TRANSITION_COVERAGE_V2,
            EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2,
            typed_common,
        )
        .unwrap();
        assert_eq!(
            typed[ROOT_STATEMENT_REPLICA_INDEX_V2].as_canonical_u64(),
            u64::from(EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2),
        );
        let jmt = epoch_chunk_coverage_statement_values(
            &typed,
            EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2,
            EPOCH_CHUNK_TRANSITION_JMT_COVERAGE_V2,
            jmt_common,
        )
        .unwrap();
        let flow = epoch_chunk_coverage_statement_values(
            &jmt,
            EPOCH_CHUNK_TRANSITION_JMT_COVERAGE_V2,
            EPOCH_CHUNK_TRANSITION_FLOW_COVERAGE_V2,
            flow_common,
        )
        .unwrap();
        let hash = epoch_chunk_coverage_statement_values(
            &flow,
            EPOCH_CHUNK_TRANSITION_FLOW_COVERAGE_V2,
            EPOCH_CHUNK_HASH_COVERAGE_V2,
            hash_common,
        )
        .unwrap();
        assert_eq!(
            hash[ROOT_STATEMENT_REPLICA_INDEX_V2].as_canonical_u64(),
            u64::from(EPOCH_CHUNK_HASH_COVERAGE_V2),
        );
        assert!(epoch_chunk_coverage_statement_values(
            &transition,
            EPOCH_CHUNK_TRANSITION_TYPED_COVERAGE_V2,
            EPOCH_CHUNK_HASH_COVERAGE_V2,
            uniqueness_lower_common,
        )
        .is_err());

        let uniqueness_lower = epoch_chunk_coverage_statement_values(
            &hash,
            EPOCH_CHUNK_HASH_COVERAGE_V2,
            EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
            uniqueness_lower_common,
        )
        .unwrap();
        assert!(epoch_chunk_coverage_statement_values(
            &hash,
            EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
            EPOCH_RANGE_FOLD_ORDINAL_V2,
            complete_common,
        )
        .is_err());

        let complete = epoch_chunk_coverage_statement_values(
            &uniqueness_lower,
            EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
            EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
            complete_common,
        )
        .unwrap();
        assert!(epoch_chunk_coverage_statement_values(
            &uniqueness_lower,
            EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
            EPOCH_RANGE_FOLD_ORDINAL_V2,
            complete_common,
        )
        .is_err());
        let finalized = epoch_chunk_coverage_statement_values(
            &complete,
            EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
            EPOCH_RANGE_FOLD_ORDINAL_V2,
            complete_common,
        )
        .unwrap();
        assert_eq!(
            finalized[ROOT_STATEMENT_REPLICA_INDEX_V2].as_canonical_u64(),
            u64::from(EPOCH_RANGE_FOLD_ORDINAL_V2),
        );
        assert_eq!(
            EpochChunkCoverageStageV2::UniquenessLower.output_coverage(4),
            EPOCH_CHUNK_COMPLETE_COVERAGE_V2,
        );
        assert_eq!(
            EpochChunkCoverageStageV2::UniquenessLower.output_coverage(5),
            EPOCH_CHUNK_UNIQUENESS_LOWER_COVERAGE_V2,
        );
        assert!(EpochChunkCoverageStageV2::UniquenessUpper
            .slice(4)
            .is_none());
        assert_eq!(
            EpochChunkCoverageStageV2::UniquenessUpper.slice(8),
            Some((4, 4)),
        );
    }

    #[test]
    fn test_epoch_chunk_group_certificate_binds_transition_identity_and_stage() {
        let mut transition_public =
            vec![KoalaBear::ZERO; plonky3_epoch_transition_air::PUBLIC_FIELDS_V2];
        let transition_common = [KoalaBear::from_u8(7); ROOT_COMMON_CAP_FIELDS_V2];
        let parent_common = [KoalaBear::from_u8(8); ROOT_COMMON_CAP_FIELDS_V2];
        let typed = epoch_chunk_group_certificate_statement_values(
            &transition_public,
            transition_common,
            EpochChunkCoverageStageV2::TransitionTyped,
            plonky3_epoch_transition_air::BINDING_SLOTS_V2,
            parent_common,
        )
        .unwrap();
        assert_eq!(
            typed[ROOT_STATEMENT_REPLICA_INDEX_V2].as_canonical_u64(),
            u64::from(
                EpochChunkCoverageStageV2::TransitionTyped
                    .certificate_ordinal(plonky3_epoch_transition_air::BINDING_SLOTS_V2),
            ),
        );

        transition_public[0] = KoalaBear::ONE;
        let substituted = epoch_chunk_group_certificate_statement_values(
            &transition_public,
            transition_common,
            EpochChunkCoverageStageV2::TransitionTyped,
            plonky3_epoch_transition_air::BINDING_SLOTS_V2,
            parent_common,
        )
        .unwrap();
        assert_ne!(
            &typed[ROOT_STATEMENT_COMMITMENT_INDEX_V2
                ..ROOT_STATEMENT_COMMITMENT_INDEX_V2 + ROOT_STATEMENT_COMMITMENT_FIELDS_V2],
            &substituted[ROOT_STATEMENT_COMMITMENT_INDEX_V2
                ..ROOT_STATEMENT_COMMITMENT_INDEX_V2 + ROOT_STATEMENT_COMMITMENT_FIELDS_V2],
        );

        let hash = epoch_chunk_group_certificate_statement_values(
            &transition_public,
            transition_common,
            EpochChunkCoverageStageV2::Hash,
            plonky3_epoch_transition_air::BINDING_SLOTS_V2,
            parent_common,
        )
        .unwrap();
        assert_ne!(
            hash[ROOT_STATEMENT_REPLICA_INDEX_V2],
            substituted[ROOT_STATEMENT_REPLICA_INDEX_V2],
        );
        assert!(epoch_chunk_group_certificate_statement_values(
            &transition_public[..transition_public.len() - 1],
            transition_common,
            EpochChunkCoverageStageV2::Hash,
            plonky3_epoch_transition_air::BINDING_SLOTS_V2,
            parent_common,
        )
        .is_err());
        assert!(epoch_chunk_group_certificate_statement_values(
            &transition_public,
            transition_common,
            EpochChunkCoverageStageV2::Hash,
            0,
            parent_common,
        )
        .is_err());
    }

